  const address=clean.match(/<([a-z][a-z0-9]*)\b[^>]*id=["']viewad-locality["'][^>]*>([\s\S]*?)<\/\1>/i);
  if(address && /kleinanzeigen\.de/.test(hostname))out.address=decode(address[2]);
  for(const m of clean.matchAll(/<(?:img|meta|div)\b[^>]*>/gi)) {
    const tag=m[0], attr=(name:string)=>tag.match(new RegExp(`(?:^|\\s)${name}\\s*=\\s*["']([^"']+)["']`,'i'))?.[1];
    // Only listing gallery/itemprop images and the page's explicit preview image.
    if(attr('property')==='og:image') {const u=imageUrl(attr('content'),base);if(u)out.images.push(u);}
    else if((/(^|\.)kleinanzeigen\.de$/.test(hostname)&&attr('data-imgsrc')) || attr('itemprop')==='image' || /(?:gallery|imagebox|expose-picture|listing-image)/i.test(attr('class')||'')) {
      const u=imageUrl(attr('data-imgsrc')||attr('data-src')||attr('data-original')||attr('src'),base);if(u)out.images.push(u);
    }
  }
  out.images=collectImages({images:out.images},base);
  return out;
}

export async function waitForDispatchSlot(db: any, owner: string, deadline: number, clock = Date.now, sleep = (ms: number) => new Promise(r => setTimeout(r, ms))) {
  const {data,error} = await db.rpc('dispatcher_slot',{p_owner:owner});
  if(error) throw error;
  const at = new Date(data).getTime();
  if(!Number.isFinite(at)) throw new Error('Invalid dispatcher slot');
  if(at>=deadline) return false;
  const wait=Math.max(0,at-clock());
  if(wait) await sleep(wait);
  return clock()<deadline;
}

type Lease = { id: string; attempt: number; claimedAt: string };

export async function claimDelivery(
  db: any,
  event: any,
): Promise<Lease | null> {
  const lease = {
    id: event.id,
    attempt: Number(event.dispatch_attempts || 0) + 1,
    claimedAt: new Date().toISOString(),
  };
  const { data, error } = await db
    .from("delivery_events")
    .update({
      status: "processing",
      dispatch_attempts: lease.attempt,
      last_attempt_at: lease.claimedAt,
    })
    .eq("id", event.id)
    .eq("status", event.status)
    .eq("dispatch_attempts", Number(event.dispatch_attempts || 0))
    .select("id")
    .maybeSingle();
  if (error) throw error;
  return data ? lease : null;
}

export async function finishDelivery(
  db: any,
  lease: Lease,
  patch: Record<string, unknown>,
) {
  const { data, error } = await db
    .from("delivery_events")
    .update(patch)
    .eq("id", lease.id)
    .eq("status", "processing")
    .eq("dispatch_attempts", lease.attempt)
    .eq("last_attempt_at", lease.claimedAt)
    .select("id")
    .maybeSingle();
  if (error) throw error;
  if (!data) throw new Error(`Delivery ${lease.id}: lease no longer owned`);
}

export async function recoverDeliveries(db: any) {
  // Longer than the hosted Edge Function lifetime. Never steal a live request.
  const { error } = await db
    .from("delivery_events")
    .update({
      status: "failed",
      delivery_outcome_unknown: true,
      next_retry_at: new Date().toISOString(),
      error_message:
        "Expired delivery lease; prior Telegram outcome may be unknown",
    })
    .eq("status", "processing")
    .lt("last_attempt_at", new Date(Date.now() - 600_000).toISOString());
  if (error) throw error;
}

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { isAdmin } from "./admin.js";
import { handleMessage, handleCallback } from "./handlers.js";
import { premium } from "./navigation.js";
import { SUPABASE_URL, db, secretCache, chatLanguages, secret, telegram, withPlan, finishUpdate } from "./runtime.js";
Deno.serve(async (request) => {
    const requestStarted=Date.now();
    let updateId=null,attempt=null,prepareMs=0,renderStarted=0,renderMs=0;
    try {
        if (request.method === "GET" || request.method === "HEAD") {
            const url = new URL(request.url);
            if (url.searchParams.get("asset") === "premium") {
                return fetch(`${SUPABASE_URL}/functions/v1/telegram-premium-image?v=20260903hd4`, { method: request.method });
            }
        }
        if (request.method !== "POST") {
            return new Response("method not allowed", { status: 405 });
        }
        let expectedSecret = await secret("telegram_webhook_secret");
        const suppliedSecret = request.headers.get("x-telegram-bot-api-secret-token") || "";
        if (suppliedSecret !== expectedSecret) {
            secretCache.delete("telegram_webhook_secret");
            expectedSecret = await secret("telegram_webhook_secret", true);
            if (suppliedSecret !== expectedSecret) {
                return new Response("unauthorized", { status: 401 });
            }
        }
        const payload = await request.json().catch(() => ({}));
        const from = payload.callback_query?.from || payload.message?.from;
        const chatId = payload.callback_query?.message?.chat?.id || payload.message?.chat?.id;
        if (!from?.id || !chatId)
            return Response.json({ ok: true, ignored: true });
        const prepareStarted=Date.now();
        const {data:prepared,error:claimError}=await db.rpc('prepare_telegram_update',{p_payload:payload});
        prepareMs=Date.now()-prepareStarted;
        const claim=prepared?.claim;
        if(claimError) throw claimError;
        if(claim===0) return Response.json({ok:true,duplicate:true});
        if(claim<0) return Response.json({ok:false,busy:true,retry_after_ms:50},{status:503,headers:{"retry-after":"0"}});
        updateId=payload.update_id;attempt=claim;
        const user = await withPlan({...prepared.user, __is_new_user:prepared.is_new_user === true}, prepared.subscription ?? null);
        user.request_update_id=updateId;
        user.request_attempt=attempt;
        user.__callback_acked=request.headers.get("x-callback-acked")==="1";
        if (!user.is_active && !isAdmin(user)) {
            await finishUpdate(updateId,attempt,true,null,{prepare_ms:prepareMs,total_ms:Date.now()-requestStarted});
            return Response.json({ ok: true, blocked: true });
        }
        chatLanguages.set(Number(chatId), String(user.ui_language || "de"));
        renderStarted=Date.now();
        if (payload.callback_query) {
            await handleCallback(payload.callback_query, user);
        }
        else if (payload.message?.chat?.type === "private" &&
            (payload.message?.text || payload.message?.document || payload.message?.photo)) {
            await handleMessage(payload.message, user);
        }
        renderMs=Date.now()-renderStarted;
        await finishUpdate(updateId,attempt,true,null,{prepare_ms:prepareMs,render_ms:renderMs,total_ms:Date.now()-requestStarted});
        return Response.json({ ok: true });
    }
    catch (error) {
        if(updateId!==null && attempt!==null) {
          try {if(renderStarted&&!renderMs)renderMs=Date.now()-renderStarted;await finishUpdate(updateId,attempt,false,String(error),{prepare_ms:prepareMs,render_ms:renderMs,total_ms:Date.now()-requestStarted});} catch(ackError){console.error('inbox_finish',String(ackError));}
        }
        console.error("telegram_command_runtime", error);
        return Response.json({ ok: false, error: "command_runtime_failed" }, { status: 500 });
    }
});

