    subscription = data;
    }
    const now = Date.now();
    const premium = user.plan_override === "free"
        ? false
        : (user.plan_override === "premium" &&
            (!user.plan_override_expires_at ||
                new Date(user.plan_override_expires_at).getTime() > now)) ||
            (!!user.referral_bonus_until &&
