            chat_id: chatId,
            menu_button: { type: "commands" },
        }),
    ];
    if (admin) {
        requests.push(
            telegram("setMyCommands", {
                commands: ADMIN_COMMANDS,
                scope: { type: "chat", chat_id: chatId },
            }),
            telegram("setMyCommands", {
                commands: ADMIN_COMMANDS,
                scope: { type: "chat", chat_id: chatId },
                language_code: "de",
            }),
        );
    }
    else {
        requests.push(
            telegram("deleteMyCommands", {
                scope: { type: "chat", chat_id: chatId },
            }),
            telegram("deleteMyCommands", {
                scope: { type: "chat", chat_id: chatId },
                language_code: "de",
            }),
        );
    }
    const results = await Promise.allSettled(requests);
    for (const result of results) {
        if (result.status === "rejected")
            console.error("telegram_command_sync", String(result.reason));
    }
}
export async function handleMessage(message, user) {
    const chatId = Number(message.chat.id);
    const text = String(message.text || "").trim();
    const [rawCommand, argument = ""] = text.split(/\s+/, 2);
    const command = rawCommand
        .toLowerCase()
        .replace(/@traumwohnunghamburgbot$/i, "");
    if (command === "/admin") {
        if (!isAdmin(user))
            return;
        return adminUsers(user, chatId);
    }
    if (command === "/announcement") {
        if (!isAdmin(user))
            return;
        return send(chatId, `${ANNOUNCEMENT_PROMPT}\n\nAntworte auf diese Nachricht mit dem Text, den alle aktiven Bot-Nutzer erhalten sollen.\n\nMaximal 3.500 Zeichen.`, {
            force_reply: true,
            selective: true,
            input_field_placeholder: "Ankündigung schreiben"
        });
    }
    if (command === "/start" || command === "/commands") {
        if (command === "/start" && argument.startsWith("ref_") && user.__is_new_user === true) {
            const { error } = await db.rpc("redeem_referral_code", {
                p_referred_user_id: user.id,
                p_code: argument.slice(4),
            });
            if (error)
                console.error("referral_register", error.message);
        }
        await syncTelegramCommands(user, chatId);
        return home(user, chatId);
    }
    if (command === "/suche")
        return startNewProfile(user, chatId);
    if (command === "/profile")
        return profile(user, chatId);
    if (command === "/gespeichert" || command === "/saved") {
        return saved(user, chatId);
    }
    if (command === "/einstellungen" || command === "/settings") {
        return settings(user, chatId);
    }
    if (command === "/pause") {
        await setPaused(user.id, true);
        return send(chatId, "⏸ Dein Suchprofil ist pausiert.");
    }
    if (command === "/resume") {
        await setPaused(user.id, false);
        return send(chatId, "▶️ Dein Suchprofil ist wieder aktiv.");
    }
    if (command === "/status")
        return renderStatus(user, chatId);
    if (command === "/hilfe" || command === "/help") {
        return send(chatId, HELP_TEXT);
    }
    if (command === "/premium")
        return premium(user, chatId);
    const repliedText = String(message.reply_to_message?.text || "");
    if (isAdmin(user) && repliedText.startsWith(ANNOUNCEMENT_PROMPT)) {
        return createAnnouncementDraft(user, chatId, text);
    }
    const autoApplyMessage = await handleAutoApplyMessage(user, message);
    if (autoApplyMessage)
        return autoApplyMessage;
    const draft = draftFor(user);
    if (user.onboarding_step === "rent_custom") {
        const value = Number(text.replace(/\./g, "").replace(",", "."));
        if (!Number.isFinite(value) || value < 100 || value > 5000) {
            return send(chatId, "Bitte einen Betrag zwischen 100 und 5.000 eingeben.");
        }
        draft.max_warm_rent = value;
        if (draft.profile_edit) {
            const slot = draft.profile_slot;
            delete draft.profile_edit;
            delete draft.edit_return;
            await persistProfile(user, draft);
            return profile(user, chatId, undefined, slot);
        }
        if (draft.edit_return) {
            delete draft.edit_return;
            return renderReview(user, chatId, undefined, draft);
        }
        await saveState(user.id, "rooms", draft, user.request_update_id, user.request_attempt);
        return send(chatId, "🚪 <b>Wie viele Zimmer brauchst du mindestens?</b>", {
            inline_keyboard: [
                [button("1+", "rooms:1"), button("2+", "rooms:2")],
                [button("3+", "rooms:3"), button("4+", "rooms:4")],
                backRow("rent"), cancelRow(),
            ],
        });
    }
    return send(chatId, "Bitte verwende die Befehle oder Buttons. Mit /hilfe siehst du alle Befehle.");
}

export async function handleCallback(query, user) {
    const chatId = Number(query.message?.chat.id);
    const messageId = Number(query.message?.message_id);
    const data = String(query.data || "");
    const ack = (text) => user.__callback_acked ? Promise.resolve() : acknowledge(query.id, text);
    if (!chatId || !messageId)
        return ack();
    if (data.startsWith("admin:")) {
        if (!isAdmin(user))
            return ack();
        if (data === "admin:list") {
            EdgeRuntime.waitUntil(ack());
            return adminUsers(user, chatId, messageId);
        }
        if (data.startsWith("admin:announcement-send:")) {
            const announcementId = data.slice("admin:announcement-send:".length);
            await ack("Ankündigung wird gesendet");
            return sendAnnouncement(user, chatId, messageId, announcementId);
        }
        if (data.startsWith("admin:announcement-cancel:")) {
            const announcementId = data.slice("admin:announcement-cancel:".length);
            await ack("Abgebrochen");
            return cancelAnnouncement(user, chatId, messageId, announcementId);
        }
        if (data.startsWith("admin:user:")) {
            EdgeRuntime.waitUntil(ack());
            return adminUser(user, chatId, messageId, data.slice("admin:user:".length));
        }
        if (data.startsWith("admin:block:")) {
            const userId = data.slice("admin:block:".length);
            try {
                await setUserBlocked(userId, true);
                await ack("Nutzer gesperrt");
            }
            catch (error) {
                await ack(String(error).includes("admin accounts") ? "Admin-Konto geschützt" : "Sperren fehlgeschlagen");
            }
            return adminUser(user, chatId, messageId, userId);
        }
        if (data.startsWith("admin:unblock:")) {
            const userId = data.slice("admin:unblock:".length);
            try {
                await setUserBlocked(userId, false);
                await ack("Nutzer entsperrt");
            }
            catch (error) {
                await ack(String(error).includes("admin accounts") ? "Admin-Konto geschützt" : "Entsperren fehlgeschlagen");
            }
            return adminUser(user, chatId, messageId, userId);
        }
        if (data.startsWith("admin:delete-confirm:")) {
            const userId = data.slice("admin:delete-confirm:".length);
            try {
                await deleteUser(userId);
                await ack("Nutzer gelöscht");
            }
            catch (error) {
                await ack(String(error).includes("admin accounts") ? "Admin-Konto geschützt" : "Löschen fehlgeschlagen");
            }
            return adminUsers(user, chatId, messageId);
        }
        if (data.startsWith("admin:delete:")) {
            const userId = data.slice("admin:delete:".length);
            EdgeRuntime.waitUntil(ack());
            return edit(chatId, messageId, "🗑 <b>Nutzer wirklich löschen?</b>\n\nSuchprofile, gespeicherte Inserate, Referral- und Abo-Zuordnungen werden dauerhaft gelöscht.", { inline_keyboard: [
                    [button("🗑 Ja, endgültig löschen", `admin:delete-confirm:${userId}`)],
                    [button("← Abbrechen", `admin:user:${userId}`)],
                ] });
        }
        if (data.startsWith("admin:set:")) {
            const parts = data.split(":");
            const userId = parts[2];
            const grant = parts[3];
            if (!userId || !["free", "7d", "30d", "3m", "life"].includes(grant)) {
                return ack();
            }
            const target = await setPlanOverride(userId, grant);
            let noticeFailed = false;
            if (grant !== "free") {
                try {
                    await send(Number(target.chat_id), adminPremiumNotice(grant));
                }
                catch (error) {
                    noticeFailed = true;
                    console.error("admin_premium_notice", error);
                }
            }
            await ack(grant === "free"
                ? "Free gesetzt"
                : noticeFailed
                    ? "Premium gesetzt · Nachricht fehlgeschlagen"
                    : `${adminGrantLabel(grant)} Premium gesetzt`);
            return adminUser(user, chatId, messageId, userId);
        }
        return ack();
    }
    if (data.startsWith("save:")) {
        const savedState = await toggleSave(user, data.slice(5));
        if (savedState !== null && user.__callback_acked) {
            try {
                const markup = structuredClone(query.message?.reply_markup || {});
                let changed = false;
                for (const row of markup.inline_keyboard || []) for (const item of row || []) {
                    if (item?.callback_data === data) {
                        item.text = savedState ? "⭐ Gespeichert" : "⭐ Speichern";
                        changed = true;
                    }
                }
                if (changed) await telegram("editMessageReplyMarkup", { chat_id: chatId, message_id: messageId, reply_markup: markup });
            } catch (error) { console.error("save_button_refresh", String(error)); }
        }
        if (savedState === null) {
            EdgeRuntime.waitUntil(ack());
            return premium(user, chatId, messageId);
        }
        return ack(savedState ? "⭐ Gespeichert" : "Entfernt");
    }
    EdgeRuntime.waitUntil(ack());
    if (data === 'platforms' || data.startsWith('platforms:')) {
        if (!user.is_premium) {
            const text = "🔒 <b>Automatische Bewerbung</b>\n\n" +
                "Die automatische Bewerbung ist mit Premium verfügbar.\n\n" +
                "Mit Premium können passende Bewerbungen automatisch über deine verbundenen Plattformen versendet werden.\n\n" +
                "Nach dem Upgrade kannst du die Einrichtung hier fortsetzen.";
            const markup = {
                inline_keyboard: [
                    [{ text: "💎 Jetzt abonnieren", url: `${PREMIUM_LINK}?client_reference_id=${encodeURIComponent(user.id)}` }],
                    [button("← Zurück", "home")],
                ],
            };
            return query.message?.photo
                ? send(chatId, text, markup)
                : edit(chatId, messageId, text, markup);
        }
        return platformSessions(user,query.message.chat,query.message?.photo?undefined:messageId,data);
    }
    if (data === "noop")
        return;
    if (data === "cancel") {
        await saveState(user.id, null, user.onboarding_state || {}, user.request_update_id, user.request_attempt);
        return home({ ...user, onboarding_step: null, onboarding_state: {} }, chatId, messageId);
    }
    if (data === "home") {
        if (query.message?.photo) {
            await telegram("deleteMessage", { chat_id: chatId, message_id: messageId }).catch(() => { });
            return home(user, chatId);
        }
        return home(user, chatId, messageId);
    }
    if (data === "new")
        return startNewProfile(user, chatId, messageId);
    if (data === "draft") {
        const draft = draftFor(user);
        const step = String(user.onboarding_step || "types");
        return renderStep(user, chatId, messageId, draft, [
            "types",
            "location",
            "boroughs",
            "neighborhoods",
            "rent",
            "rent_custom",
            "roomarea",
            "rooms",
            "area",
            "review",
        ].includes(step)
            ? step
            : "types");
    }
    if (data === "profile" || data === "profiles")
        return profile(user, chatId, messageId);
    if (data === "p:view:1")
        return profile(user, chatId, messageId, 1);
    if (data.startsWith("profile:view:"))
        return profile(user, chatId, messageId, Number(data.split(":")[2]));
    if (data.startsWith("profile:edit-field:")) {
        const parts = data.split(":");
        const slot = Number(parts[2]);
        const field = parts[3];
        if (!Number.isInteger(slot) || slot < 1 || slot > profileLimit(user))
            return;
        const { data: current, error } = await db
            .from("search_profiles")
            .select("*")
            .eq("user_id", user.id)
            .eq("profile_slot", slot)
            .maybeSingle();
        if (error)
            throw error;
        if (!current)
            return profile(user, chatId, messageId);
        const draft = await draftFromProfile(current);
        if (field === "types")
            return renderTypes(user, chatId, messageId, draft);
        if (field === "location")
            return renderLocation(user, chatId, messageId, draft);
        if (field === "rent")
            return renderRent(user, chatId, messageId, draft);
        if (field === "roomarea")
            return renderRooms(user, chatId, messageId, draft);
        if (field === "rooms")
            return renderRooms(user, chatId, messageId, draft);
        if (field === "area")
            return renderArea(user, chatId, messageId, draft);
        return profileEditMenu(user, chatId, messageId, slot);
    }
    if (data.startsWith("profile:edit:")) {
        return profileEditMenu(user, chatId, messageId, Number(data.split(":")[2]));
    }
    if (data.startsWith("profile:delete-confirm:")) {
        const slot = Number(data.split(":")[2]);
        if (!Number.isInteger(slot) || slot < 1 || slot > profileLimit(user))
            return;
        const { error } = await db
            .from("search_profiles")
            .delete()
            .eq("user_id", user.id)
            .eq("profile_slot", slot);
        if (error)
            throw error;
        return profile(user, chatId, messageId);
    }
    if (data.startsWith("profile:delete:")) {
        const slot = Number(data.split(":")[2]);
        if (!Number.isInteger(slot) || slot < 1 || slot > profileLimit(user))
            return;
        return edit(chatId, messageId, "🗑 <b>Suchprofil löschen?</b>\n\nDiese Aktion kann nicht rückgängig gemacht werden.", { inline_keyboard: [
                [button("🗑 Ja, löschen", `profile:delete-confirm:${slot}`)],
                [button("← Abbrechen", `profile:view:${slot}`)],
            ] });
    }
    if (data.startsWith("profile:pause:") || data.startsWith("profile:resume:")) {
        const slot = Number(data.split(":")[2]);
        await setPaused(user.id, data.startsWith("profile:pause:"), slot);
        return profile(user, chatId, messageId, slot);
    }
    if (data === "saved")
        return saved(user, chatId, messageId, 0);
    if (data.startsWith("saved:")) {
        return saved(user, chatId, messageId, Number(data.slice(6)) || 0);
    }
    if (data === "settings")
        return settings(user, chatId, messageId);
    if (data === "referral")
        return referralPage(user, chatId, messageId);
    if (data === "language")
        return languagePage(user, chatId, messageId);
    if (data.startsWith("lang:")) {
        const code = data.slice(5);
        if (!["de", "en", "ckb", "ku", "prs", "fa", "ru", "tr", "ar"].includes(code))
            return;
        const { error } = await db.from("bot_users").update({ ui_language: code, updated_at: new Date().toISOString() }).eq("id", user.id);
        if (error)
            throw error;
        chatLanguages.set(chatId, code);
        return settings({ ...user, ui_language: code }, chatId, messageId);
    }
    if (data === "help") {
        return edit(chatId, messageId, HELP_TEXT, {
            inline_keyboard: [[button("← Zurück", "home")]],
        });
    }
    if (data === "premium") {
        if (query.message?.photo) {
            await telegram("deleteMessage", { chat_id: chatId, message_id: messageId }).catch(() => { });
            return premium(user, chatId);
        }
        return premium(user, chatId, messageId);
    }
    if (data === "portal") {
        if (query.message?.photo)
            await telegram("deleteMessage", { chat_id: chatId, message_id: messageId }).catch(() => { });
        const url = await secret("stripe_portal_url").catch(() => null);
        const valid = url && /^https:\/\/billing\.stripe\.com\//.test(url);
        return edit(chatId, messageId, valid
            ? "💳 <b>Abo verwalten</b>"
            : "💳 Das Stripe Customer Portal ist aktuell noch nicht konfiguriert.", {
            inline_keyboard: [
                ...(valid ? [[{ text: "💳 Abo verwalten", url }]] : []),
                [button("← Premium", "premium")],
            ],
        });
    }
    if (data === "pause") {
        await setPaused(user.id, true);
        return edit(chatId, messageId, "⏸ Dein Suchprofil ist pausiert.", homeKeyboard(user));
    }
    if (data === "resume") {
        await setPaused(user.id, false);
        return edit(chatId, messageId, "▶️ Dein Suchprofil ist wieder aktiv.", homeKeyboard(user));
    }
    if (data === "status")
        return renderStatus(user, chatId, messageId);
    const draft = draftFor(user);
    if (data === "types")
        return renderTypes(user, chatId, messageId, draft);
    if (data === "location")
        return renderLocation(user, chatId, messageId, draft);
    if (data === "boroughs") {
        return renderBoroughs(user, chatId, messageId, draft);
    }
    if (data === "neighborhoods") {
        return renderNeighborhoods(user, chatId, messageId, draft);
    }
    if (data === "rent")
        return renderRent(user, chatId, messageId, draft);
    if (data === "roomarea")
        return renderRooms(user, chatId, messageId, draft);
    if (data === "rooms")
        return renderRooms(user, chatId, messageId, draft);
    if (data === "area")
        return renderArea(user, chatId, messageId, draft);
    if (data.startsWith("edit:")) {
        draft.edit_return = true;
        const step = data.slice(5);
        if (step === "types")
            return renderTypes(user, chatId, messageId, draft);
        if (step === "location") {
            return renderLocation(user, chatId, messageId, draft);
        }
        if (step === "rent")
            return renderRent(user, chatId, messageId, draft);
        if (step === "roomarea")
            return renderRooms(user, chatId, messageId, draft);
        if (step === "rooms")
            return renderRooms(user, chatId, messageId, draft);
        if (step === "area")
            return renderArea(user, chatId, messageId, draft);
    }
    if (data.startsWith("type:")) {
        const value = data.slice(5);
        if (!PROPERTY_TYPES.includes(value)) {
            return renderTypes(user, chatId, messageId, draft);
        }
        const hadExistingLocation = ["all_hamburg", "boroughs", "neighborhoods"].includes(String(draft.location_mode || ""));
        const categoryEdit = draft.profile_edit === true || draft.edit_return === true;
        draft.property_types = [value];
        draft.min_rooms = null;
        draft.min_area_sqm = null;
        draft.min_room_area_sqm = null;
        if (categoryEdit) {
            delete draft.profile_edit;
            delete draft.edit_return;
        }
        return categoryEdit && hadExistingLocation
            ? renderRent(user, chatId, messageId, draft)
            : renderLocation(user, chatId, messageId, draft);
    }
    if (data.startsWith("loc:")) {
        const value = data.slice(4);
        if (value === "all") {
            draft.location_mode = "all_hamburg";
            draft.borough_ids = [];
            draft.neighborhood_ids = [];
            return afterSelection(user, chatId, messageId, draft, "rent");
        }
        if (value === "boroughs") {
            draft.location_mode = "boroughs";
            draft.neighborhood_ids = [];
            return renderBoroughs(user, chatId, messageId, draft);
        }
        if (value === "neighborhoods") {
            draft.location_mode = "neighborhoods";
            draft.borough_ids = [];
            return renderNeighborhoods(user, chatId, messageId, draft);
        }
    }
    if (data.startsWith("borough:")) {
        const value = data.slice(8);
        const geo = await geography();
        if (value === "all") {
            draft.borough_ids = geo.boroughs.map((entry) => entry.id);
        }
        else if (value === "clear") {
            draft.borough_ids = [];
        }
        else if (value === "done") {
            if (!draft.borough_ids.length) {
                return renderBoroughs(user, chatId, messageId, draft);
            }
            return afterSelection(user, chatId, messageId, draft, "rent");
        }
        else {
            const id = Number(value);
            if (geo.boroughs.some((entry) => entry.id === id)) {
                draft.borough_ids = draft.borough_ids.includes(id)
                    ? draft.borough_ids.filter((entry) => entry !== id)
                    : [...draft.borough_ids, id];
            }
        }
        return renderBoroughs(user, chatId, messageId, draft);
    }
    if (data.startsWith("neighborhood:")) {
        const value = data.slice(13);
        const geo = await geography();
        if (value === "all") {
            draft.neighborhood_ids = geo.neighborhoods.map((entry) => entry.id);
        }
        else if (value === "clear") {
            draft.neighborhood_ids = [];
        }
        else if (value === "prev") {
            draft.neighborhood_page = Math.max(0, draft.neighborhood_page - 1);
        }
        else if (value === "next") {
            const pages = Math.max(1, Math.ceil(geo.neighborhoods.length / NEIGHBORHOODS_PER_PAGE));
            draft.neighborhood_page = Math.min(pages - 1, draft.neighborhood_page + 1);
        }
        else if (value === "done") {
            if (!draft.neighborhood_ids.length) {
                return renderNeighborhoods(user, chatId, messageId, draft);
            }
            return afterSelection(user, chatId, messageId, draft, "rent");
        }
        else {
            const id = Number(value);
            if (geo.neighborhoods.some((entry) => entry.id === id)) {
                draft.neighborhood_ids = draft.neighborhood_ids.includes(id)
                    ? draft.neighborhood_ids.filter((entry) => entry !== id)
                    : [...draft.neighborhood_ids, id];
            }
        }
        return renderNeighborhoods(user, chatId, messageId, draft);
    }
    if (data.startsWith("rent:")) {
        const value = data.slice(5);
        if (value === "custom") {
            return renderCustomRent(user, chatId, messageId, draft);
        }
        const amount = Number(value);
        if (RENT_PRESETS.has(amount)) {
            draft.max_warm_rent = amount;
            return afterSelection(user, chatId, messageId, draft, nextSizeStep(draft));
        }
        return renderRent(user, chatId, messageId, draft);
    }
    if (data.startsWith("roomarea:")) {
        return renderRooms(user, chatId, messageId, draft);
    }
    if (data.startsWith("rooms:")) {
        const rooms = Number(data.slice(6));
        if (ROOM_PRESETS.has(rooms)) {
            draft.min_rooms = rooms;
            return afterSelection(user, chatId, messageId, draft, "area");
        }
        return renderRooms(user, chatId, messageId, draft);
    }
    if (data.startsWith("area:")) {
        const area = Number(data.slice(5));
        if (AREA_PRESETS.has(area)) {
            draft.min_area_sqm = area;
            return afterSelection(user, chatId, messageId, draft, "review");
        }
        return renderArea(user, chatId, messageId, draft);
    }
    if (data === "profile:save" || data === "s:save") {
        const issue = validateDraft(draft);
        if (issue)
            return renderStep(user, chatId, messageId, draft, issue);
        const referralReward = await persistProfile(user, draft);
        const result = await edit(chatId, messageId, "✅ Deine Suche ist aktiv. Neue passende Inserate werden automatisch zugestellt.", homeKeyboard({ ...user, onboarding_step: null }));
        if (referralReward?.status === "rewarded") {
            await sendCelebration(chatId, "💎 <b>30 Tage Premium kostenlos aktiviert</b>\n\n" +
                "Dein erstes Suchprofil ist erstellt und dir wurden 30 Tage Premium kostenlos gutgeschrieben.\n\n" +
                "Viel Erfolg und viel Spaß bei deiner Wohnungssuche! 🏠");
        }
        return result;
    }
}

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2.112.4";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SECRET_KEYS = JSON.parse(Deno.env.get("SUPABASE_SECRET_KEYS") || "{}");
const ADMIN_KEY = SECRET_KEYS.default || Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const db = createClient(SUPABASE_URL, ADMIN_KEY, {
  auth: { persistSession: false, autoRefreshToken: false },
});

const PAYMENT_LINK_ID = "plink_1UAy8Z2NorDNIWqI9h5j73q0";
const ACTIVE_STATUSES = new Set(["active", "trialing"]);
const PARTY_EFFECT_ID = "5046509860389126442";

async function requiredSecret(name: string) {
  const { data, error } = await db.rpc("get_bot_secret", { secret_name: name });
  if (error || !data) throw new Error(`secret ${name} unavailable`);
  return String(data);
}

function hex(buffer: ArrayBuffer) {
  return [...new Uint8Array(buffer)]
    .map((value) => value.toString(16).padStart(2, "0"))
    .join("");
}

function timingSafeEqual(a: string, b: string) {
  if (a.length !== b.length) return false;
  let result = 0;
  for (let i = 0; i < a.length; i++) {
    result |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return result === 0;
}

async function verifyStripeSignature(body: string, header: string, secret: string) {
  const parts = header.split(",");
  const timestamp = parts.find((part) => part.startsWith("t="))?.slice(2);
  const signatures = parts
    .filter((part) => part.startsWith("v1="))
    .map((part) => part.slice(3));
  if (
    !timestamp ||
    !signatures.length ||
    Math.abs(Date.now() / 1000 - Number(timestamp)) > 300
  ) {
    return false;
  }

  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const expected = hex(
    await crypto.subtle.sign(
      "HMAC",
      key,
      new TextEncoder().encode(`${timestamp}.${body}`),
    ),
  );
  return signatures.some((signature) => timingSafeEqual(expected, signature));
}

function isoFromUnix(value: unknown) {
  const n = Number(value);
  return Number.isFinite(n) && n > 0
    ? new Date(n * 1000).toISOString()
    : null;
}

function validUuid(value: unknown) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    String(value || ""),
  );
}

function stripeId(value: any) {
  return typeof value === "string" ? value : String(value?.id || "");
}

async function existingSubscription(
  userId?: string,
  subscriptionId?: string,
  customerId?: string,
) {
  let query = db.from("user_subscriptions").select("*");
  if (userId) query = query.eq("user_id", userId);
  else if (subscriptionId && customerId) {
    query = query.or(
      `stripe_subscription_id.eq.${subscriptionId},stripe_customer_id.eq.${customerId}`,
    );
  } else if (subscriptionId) {
    query = query.eq("stripe_subscription_id", subscriptionId);
  } else if (customerId) {
    query = query.eq("stripe_customer_id", customerId);
  } else {
    return null;
  }
  const { data, error } = await query.limit(1).maybeSingle();
  if (error) throw error;
  return data || null;
}

async function applyEntitlement(
  userId: string,
  patch: Record<string, unknown>,
  eventCreated: number,
  enforceOrdering = true,
) {
  const old = await existingSubscription(userId);
  if (
    enforceOrdering &&
    old &&
    Number(old.last_event_created || 0) > eventCreated
  ) {
    return;
  }

  const row: any = {
    user_id: userId,
    provider: "stripe",
    ...patch,
    last_event_created: enforceOrdering
      ? eventCreated
      : Number(old?.last_event_created || 0),
    updated_at: new Date().toISOString(),
  };
  const { error } = await db
    .from("user_subscriptions")
    .upsert(row, { onConflict: "user_id" });
  if (error) throw error;

  const status = String(row.status || old?.status || "inactive");
  const periodEnd = row.current_period_end ?? old?.current_period_end;
  const stripePremium =
    ACTIVE_STATUSES.has(status) &&
    (!periodEnd || new Date(String(periodEnd)).getTime() > Date.now());

  const { data: user, error: userError } = await db
    .from("bot_users")
    .select("plan_override,plan_override_expires_at,referral_bonus_until")
    .eq("id", userId)
    .maybeSingle();
  if (userError) throw userError;

  const premium = user?.plan_override === "free"
    ? false
    : (user?.plan_override === "premium" &&
        (!user.plan_override_expires_at ||
          new Date(user.plan_override_expires_at).getTime() > Date.now())) ||
      (!!user?.referral_bonus_until &&
        new Date(user.referral_bonus_until).getTime() > Date.now()) ||
      stripePremium;

  if (premium) {
    const { data: profiles, error: profileError } = await db
      .from("search_profiles")
      .select("id")
      .eq("user_id", userId);
    if (profileError) throw profileError;
    const profileIds = (profiles || []).map((profile) => profile.id);
    if (profileIds.length) {
      const { error: deliveryError } = await db
        .from("delivery_events")
        .update({ next_retry_at: null })
        .in("profile_id", profileIds)
        .eq("status", "pending")
        .gt("next_retry_at", new Date().toISOString());
      if (deliveryError) throw deliveryError;
    }
  } else {
    const { error: profileError } = await db
      .from("search_profiles")
      .update({ is_active: false, updated_at: new Date().toISOString() })
      .eq("user_id", userId)
      .gt("profile_slot", 1);
    if (profileError) throw profileError;
  }
}

async function applySubscriptionObject(object: any, eventCreated: number) {
  const subscriptionId = String(object.id || "");
  const customerId = stripeId(object.customer);
  const old = await existingSubscription(undefined, subscriptionId, customerId);
  if (!old || Number(old.last_event_created || 0) > eventCreated) return;

  const itemPeriodEnds = (object.items?.data || []).map((item: any) =>
    Number(item.current_period_end || 0)
  );
  const currentPeriodEnd =
    Number(object.current_period_end || 0) || Math.max(0, ...itemPeriodEnds);
  await applyEntitlement(
    String(old.user_id),
    {
      stripe_customer_id: customerId || old.stripe_customer_id,
      stripe_subscription_id: subscriptionId || old.stripe_subscription_id,
      status: String(object.status || old.status || "inactive"),
      current_period_end: isoFromUnix(currentPeriodEnd),
      cancel_at_period_end: !!object.cancel_at_period_end,
    },
    eventCreated,
    true,
  );
}

async function telegramMessage(
  userId: string,
  text: string,
  replyMarkup?: Record<string, unknown>,
  messageEffectId?: string,
) {
  const { data: user, error } = await db
    .from("bot_users")
    .select("chat_id")
    .eq("id", userId)
    .maybeSingle();
  if (error) throw error;
  if (!user?.chat_id) return;

  const token = await requiredSecret("telegram_bot_token_runtime");
  const sendBody = (effect?: string) => JSON.stringify({
    chat_id: user.chat_id,
    text,
    parse_mode: "HTML",
    reply_markup: replyMarkup,
    ...(effect ? { message_effect_id: effect } : {}),
  });
  let response = await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: sendBody(messageEffectId),
  });
  let result = await response.json().catch(() => ({}));
  if ((!response.ok || !result.ok) && messageEffectId) {
    response = await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: sendBody(),
    });
    result = await response.json().catch(() => ({}));
  }
  if (!response.ok || !result.ok) {
    throw new Error(
      `Telegram sendMessage ${response.status}: ${String(result?.description || "failed")}`,
    );
  }
}

async function claimEvent(eventId: string, eventType: string, eventCreated: number) {
  const { data, error } = await db.rpc("claim_stripe_webhook_event", {
    p_event_id: eventId,
    p_event_type: eventType,
    p_event_created: eventCreated,
  });
  if (error) throw error;
  return String(data || "");
}

async function finishEvent(
  eventId: string,
  status: "processed" | "failed",
  errorMessage: string | null = null,
) {
  const { error } = await db.rpc("finish_stripe_webhook_event", {
    p_event_id: eventId,
    p_status: status,
    p_error: errorMessage,
  });
  if (error) throw error;
}

Deno.serve(async (req: Request) => {
  let eventId = "";
  let claimed = false;
  try {
    if (req.method !== "POST") {
      return new Response("method not allowed", { status: 405 });
    }

    const body = await req.text();
    const signature = req.headers.get("stripe-signature") || "";
    const signingSecret = await requiredSecret("stripe_webhook_signing_secret");
    if (!(await verifyStripeSignature(body, signature, signingSecret))) {
      return new Response("bad signature", { status: 400 });
    }

    const event = JSON.parse(body);
    eventId = String(event.id || "");
    const eventType = String(event.type || "");
    const eventCreated = Number(event.created || 0);
    const object = event.data?.object || {};
    if (!eventId) return new Response("missing event id", { status: 400 });

    const claim = await claimEvent(eventId, eventType, eventCreated);
    if (claim === "duplicate") {
      return Response.json({ received: true, duplicate: true });
    }
    if (claim === "busy") {
      return Response.json({ received: true, processing: true });
    }
    if (claim !== "claimed") throw new Error(`unexpected claim result: ${claim}`);
    claimed = true;

    if (
      eventType === "checkout.session.completed" ||
      eventType === "checkout.session.async_payment_succeeded"
    ) {
      const isExpectedCheckout =
        String(object.payment_link || "") === PAYMENT_LINK_ID &&
        String(object.metadata?.plan || "") === "premium_monthly";
      const userId = String(object.client_reference_id || "");
      if (isExpectedCheckout && validUuid(userId)) {
        const paid =
          eventType === "checkout.session.async_payment_succeeded" ||
          String(object.payment_status || "") === "paid";
        const customerId = stripeId(object.customer) || null;
        if (paid) {
          const { error: overrideError } = await db
            .from("bot_users")
            .update({
              plan_override: null,
              plan_override_expires_at: null,
              updated_at: new Date().toISOString(),
            })
            .eq("id", userId)
            .eq("plan_override", "free");
          if (overrideError) throw overrideError;
        }
        await applyEntitlement(
          userId,
          {
            stripe_customer_id: customerId,
            stripe_subscription_id: stripeId(object.subscription) || null,
            status: paid ? "active" : "incomplete",
            cancel_at_period_end: false,
          },
          eventCreated,
          false,
        );
        if (paid) {
          try {
            await telegramMessage(
              userId,
              "🎉 <b>Danke für dein Abo!</b>\n\n" +
                "💎 Dein Traumwohnung Premium-Abo ist jetzt aktiv.\n\n" +
                "<b>Ab sofort profitierst du von:</b>\n" +
                "⚡ Sofortiger Zustellung neuer passender Inserate\n" +
                "🔎 Bis zu 4 Suchprofile\n" +
                "🤖 Auto-Bewerbung\n" +
                "🔓 Baugenossenschafts-Angebote öffnen\n" +
                "⭐️ Inserate speichern\n\n" +
                "Viel Erfolg bei der Wohnungssuche! 🏠",
              {
                inline_keyboard: [[
                  { text: "🏠 Zum Menü", callback_data: "home" },
                ]],
              },
              PARTY_EFFECT_ID,
            );
          } catch (noticeError) {
            console.error("premium_activation_notice", noticeError);
          }
        }
      }
    } else if (
      eventType === "customer.subscription.created" ||
      eventType === "customer.subscription.updated" ||
      eventType === "customer.subscription.deleted"
    ) {
      await applySubscriptionObject(object, eventCreated);
    } else if (eventType === "invoice.payment_failed") {
      const customerId = stripeId(object.customer);
      const subscription = await existingSubscription(undefined, undefined, customerId);
      if (subscription) {
        await telegramMessage(
          String(subscription.user_id),
          "⚠️ <b>Premium-Zahlung fehlgeschlagen</b>\n\nBitte aktualisiere deine Zahlungsmethode über „Abo verwalten“.",
          {
            inline_keyboard: [[
              { text: "💳 Abo verwalten", callback_data: "portal" },
            ]],
          },
        );
      }
    }

    await finishEvent(eventId, "processed");
    return Response.json({ received: true });
  } catch (error) {
    console.error(error);
    if (claimed && eventId) {
      try {
        await finishEvent(
          eventId,
          "failed",
          error instanceof Error ? error.message : String(error),
        );
      } catch (finishError) {
        console.error("stripe_webhook_finish_failed", finishError);
      }
    }
    return Response.json(
      { received: false, error: error instanceof Error ? error.message : String(error) },
      { status: 500 },
    );
  }
});

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2.112.4";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SECRET_KEYS = JSON.parse(Deno.env.get("SUPABASE_SECRET_KEYS") || "{}");
const ADMIN_KEY = SECRET_KEYS.default || Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const db = createClient(SUPABASE_URL, ADMIN_KEY, {
  auth: { persistSession: false, autoRefreshToken: false },
});
const STRIPE_API_VERSION = "2026-06-24.dahlia";

async function secret(name: string, required = true) {
  const { data, error } = await db.rpc("get_bot_secret", { secret_name: name });
  if (error || !data) {
    if (required) throw new Error(`secret ${name} unavailable`);
    return null;
  }
  return String(data);
}

async function stripeCredit(
  apiKey: string,
  customerId: string,
  referral: any,
) {
  const amount = Math.max(1, Number(referral.reward_amount_cents || 499));
  const params = new URLSearchParams();
  params.set("amount", String(-amount));
  params.set("currency", "eur");
  params.set("description", "Empfehlungsgutschrift Traumwohnung Premium");
  params.set("metadata[referral_id]", referral.id);
  params.set("metadata[referred_user_id]", referral.referred_user_id);
  const response = await fetch(
    `https://api.stripe.com/v1/customers/${encodeURIComponent(customerId)}/balance_transactions`,
    {
      method: "POST",
      headers: {
        authorization: `Bearer ${apiKey}`,
        "content-type": "application/x-www-form-urlencoded",
        "stripe-version": STRIPE_API_VERSION,
        "idempotency-key": `referral-reward-${referral.id}`,
      },
      body: params,
    },
  );
  const result = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(
      `Stripe ${response.status}: ${String(result?.error?.message || "request failed")}`,
    );
  }
  return result;
}

async function notify(userId: string, amount: number) {
  const [{ data: user }, token] = await Promise.all([
    db.from("bot_users").select("chat_id").eq("id", userId).maybeSingle(),
    secret("telegram_bot_token_runtime"),
  ]);
  if (!user?.chat_id || !token) return;
  await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      chat_id: user.chat_id,
      parse_mode: "HTML",
      text: `🎁 <b>Empfehlungsgutschrift erhalten</b>\n\nDir wurden ${(amount / 100).toFixed(2).replace(".", ",")} € in Stripe gutgeschrieben.`,
    }),
  });
}

async function run() {
  const apiKey = await secret("stripe_restricted_api_key", false);
  if (!apiKey) {
    return { configured: false, processed: 0, deferred: 0, failed: 0 };
  }

  const { data: referrals, error } = await db
    .from("referrals")
    .select(
      "id,referrer_user_id,referred_user_id,status,rewarded_at,reward_amount_cents",
    )
    .eq("status", "qualified")
    .is("rewarded_at", null)
    .order("qualified_at")
    .limit(50);
  if (error) throw error;

  const totals = { configured: true, processed: 0, deferred: 0, failed: 0 };
  for (const referral of referrals || []) {
    try {
      const { data: subscription, error: subscriptionError } = await db
        .from("user_subscriptions")
        .select("stripe_customer_id")
        .eq("user_id", referral.referrer_user_id)
        .maybeSingle();
      if (subscriptionError) throw subscriptionError;
      if (!subscription?.stripe_customer_id) {
        totals.deferred++;
        continue;
      }

      const transaction = await stripeCredit(
        apiKey,
        subscription.stripe_customer_id,
        referral,
      );
      const { data: updated, error: updateError } = await db
        .from("referrals")
        .update({
          status: "rewarded",
          rewarded_at: new Date().toISOString(),
          stripe_credit_transaction_id: String(transaction.id || "") || null,
        })
        .eq("id", referral.id)
        .eq("status", "qualified")
        .is("rewarded_at", null)
        .select("id")
        .maybeSingle();
      if (updateError) throw updateError;
      if (!updated) continue;
      totals.processed++;
      try {
        await notify(
          referral.referrer_user_id,
          Number(referral.reward_amount_cents || 499),
        );
      } catch (noticeError) {
        console.error("referral_notice", noticeError);
      }
    } catch (processingError) {
      totals.failed++;
      console.error("referral_reward", referral.id, processingError);
    }
  }
  return totals;
}

Deno.serve(async (req: Request) => {
  try {
    if (req.method !== "POST") {
      return new Response("method not allowed", { status: 405 });
    }
    if (
      (req.headers.get("x-internal-secret") || "") !==
      (await secret("internal_worker_secret"))
    ) {
      return new Response("unauthorized", { status: 401 });
    }
    return Response.json({ ok: true, totals: await run() });
  } catch (error) {
    console.error(error);
    return Response.json(
      { ok: false, error: error instanceof Error ? error.message : String(error) },
      { status: 500 },
    );
  }
});

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import {likelyFastAction,renderFast} from './fast-ui.ts';

const URL=Deno.env.get('SUPABASE_URL')!;
const KEYS=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');
const KEY=KEYS.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
const CORE=`${URL}/functions/v1/telegram-ui?forceFunctionRegion=eu-west-1`;
const OAUTH_BRIDGE=`${URL}/functions/v1/telegram-oauth-bridge?forceFunctionRegion=eu-west-1`;
const WEBHOOK_SECRET_SHA256="8de81c929dcff4e2d20eeedd034518126c99d775b84664d85635f87c7f2ad010";
let webhookSecretHash=WEBHOOK_SECRET_SHA256;
const secretCache=new Map<string,{value:string,expiresAt:number}>();
const secretInflight=new Map<string,Promise<string>>();

function headers(){return {apikey:KEY,Authorization:`Bearer ${KEY}`,'content-type':'application/json'};}
async function rpc(name:string,body:Record<string,unknown>){
 const r=await fetch(`${URL}/rest/v1/rpc/${name}`,{method:'POST',headers:headers(),body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});
 const data=await r.json().catch(()=>null);if(!r.ok)throw Error(`${name}:${r.status}`);return data;
}
async function secret(name:string,force=false){
 const cached=secretCache.get(name);if(!force&&cached&&cached.expiresAt>Date.now())return cached.value;
 if(!force&&secretInflight.has(name))return secretInflight.get(name)!;
 const task=(async()=>{const data=await rpc('get_bot_secret',{secret_name:name});if(!data)throw Error(name+' unavailable');const value=String(data);const ttl=(name==='telegram_webhook_secret'||name==='telegram_bot_token_runtime')?3600000:300000;secretCache.set(name,{value,expiresAt:Date.now()+ttl});return value;})();
 secretInflight.set(name,task);try{return await task}finally{secretInflight.delete(name)}
}
void secret('telegram_bot_token_runtime').catch(error=>console.error('telegram_token_prewarm',String(error)));
async function sha256Hex(value:string){
 const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));
 return Array.from(new Uint8Array(digest),x=>x.toString(16).padStart(2,'0')).join('');
}
async function validWebhookSecret(supplied:string){
 if(!supplied)return false;
 const suppliedHash=await sha256Hex(supplied);
 if(suppliedHash===webhookSecretHash)return true;
 secretCache.delete('telegram_webhook_secret');
 const expected=await secret('telegram_webhook_secret',true);
 if(supplied!==expected)return false;
 webhookSecretHash=await sha256Hex(expected);
 return true;
}
function parsed(body:string){try{return JSON.parse(body)}catch{return null}}
function direct(method:string,params:Record<string,unknown>){return Response.json({method,...params});}
async function telegram(method:string,params:Record<string,unknown>){
 let token=await secret('telegram_bot_token_runtime');
 const send=async(t:string)=>{const r=await fetch(`https://api.telegram.org/bot${t}/${method}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(params),signal:AbortSignal.timeout(15000)});return{r,data:await r.json().catch(()=>null)}};
 let out=await send(token);
 if(!out.r.ok&&(out.r.status===401||out.r.status===404)){secretCache.delete('telegram_bot_token_runtime');token=await secret('telegram_bot_token_runtime',true);out=await send(token)}
 if(!out.r.ok||!out.data?.ok)throw Error(String(out.data?.description||`telegram:${out.r.status}`));return out.data.result;
}
async function acknowledge(id:string){const started=Date.now();try{await telegram('answerCallbackQuery',{callback_query_id:id});return Date.now()-started}catch(error){console.error('telegram_fast_ack',String(error));return null}}
async function recordMetric(updateId:number,metrics:Record<string,number|string>){try{await rpc('record_telegram_fast_metric',{p_update_id:updateId,p_metrics:metrics})}catch(error){console.error('telegram_fast_metric',String(error))}}
async function forward(body:string,expected:string,target:string,extraHeaders:Record<string,string>={}){
 const r=await fetch(target,{method:'POST',headers:{'content-type':'application/json','x-telegram-bot-api-secret-token':expected,...extraHeaders},body,signal:AbortSignal.timeout(50000)});
 return new Response(await r.text(),{status:r.status,headers:{'content-type':r.headers.get('content-type')||'application/json'}});
}
async function forwardToCore(body:string,expected:string,callbackAcked=false){
