  .replace(/&euro;|€/g,' euro ').replace(/&nbsp;|&#160;/g,' ').replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
}
function decodeImmoweltEmbeddedText(value:any){
