 const forward=/"(?:label|name|text|title|displayName|displayValue)"\s*:\s*"([^"]{1,180})"[^{}]{0,260}"(?:value|id|key|code)"\s*:\s*(?:"([^"]{1,120})"|([0-9]{1,12}))/gi;
