  await recordRefreshResult(db,userId,PROVIDER,false,`refresh_http_${response?.status||0}`).catch(()=>{});
  return{ok:false,error:'session_refresh_failed',cookies,userAgent,refreshed:false,httpStatus:response?.status||null};
